UPDATE businesses SET description = 'Ysterman Safety and Security CC, based in Klerksoord, Akasia, specialises in custom steel manufacturing alongside powder coating and sandblasting services. Its custom steel manufacturing work covers bespoke solutions designed around each client''s needs, whether that calls for intricate decorative designs or more robust structural steelwork. The business designs and manufactures security gates intended to combine strength and durability with a finished, aesthetic appearance, with gates custom-made to suit the specific security requirements of residential, commercial and industrial properties. Alongside its manufacturing work, Ysterman offers a professional sandblasting service used to clean and prepare metal surfaces before further treatment, removing rust, old paint and other contaminants so the surface is left smooth and ready to accept specialised coatings or other follow-on applications. Together, these services position the business as a combined steel fabrication, security-gate and surface-preparation provider for Pretoria''s northern suburbs.', source_urls = json_insert(CASE WHEN json_valid(source_urls) AND json_type(source_urls) = 'array' THEN source_urls ELSE '[]' END, '$[#]', 'http://www.ysterman.co.za/'), description_enriched_at = datetime('now') WHERE slug = 'ysterman-safety-and-security-cc-akasia' AND description = 'Ysterman Safety and Security CC specialises in custom steel manufacturing and security products, including security gates, sandblasting and powder coating, for residential, commercial and industrial properties in Akasia.' AND description_enriched_at IS NULL AND length(COALESCE(description, '')) < 700
